"""Exact-scope review findings and reproducible evidence checks, §§ 55–71."""
from pathlib import Path
from datetime import datetime,timezone
import re,json,hashlib,sys,xml.etree.ElementTree as E
W=Path(__file__).resolve().parent;D=W/'sources/review-p55-p71'
IDS=['p55','p56','p57','p58','p59','p60','p61','p62','p62a','p63','p64','p64a','p65','p65a','p66','p67','p68','p69','p70','p71']
def save(p,o):p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def sht(t):return hashlib.sha256(t.encode()).hexdigest()
def blocks(s):return {m[1]:m[2].strip() for m in re.finditer(r'^=== (\S+)\s*\n(.*?)(?=^=== |\Z)',s,re.S|re.M)}
notes={
'p55':('corrected','Alle fünf Absätze geprüft. Klagegründe und Sperre bei demselben Streitgegenstand zwischen denselben Parteien präzisiert; Fassung seit 16.01.2026 mit anhängigem Amtsantrag, Herkunftsberechtigung und historischem Benutzungsstichtag berücksichtigt. Einrede und verschiedene Fünfjahreszeiträume sowie § 26 Abs. 5 und § 158 Abs. 6 ergänzt. Fehlerhafte Gleichsetzung von Antragswaren und Benutzungswaren beseitigt: Umfang der älteren Marke und anschließende Ähnlichkeitsprüfung getrennt. Rechtsnachfolge und Registermeldungen erklärt.'),
'p56':('retained','Alle drei Absätze gelesen. Zuständigkeiten von Markenstellen und Markenabteilungen, Einzelprüfer, eingeschränkte Befugnisse des gehobenen Dienstes und mindestens drei Mitglieder geprüft. Ausnahme der Entscheidung nach § 53 von der Einzelbearbeitung zutreffend erklärt; Verknüpfung mit Entscheiderstatus nach § 64 bleibt sachgerecht.'),
'p57':('corrected','Beide Absätze und tatsächlicher Umfang der Verweisung geprüft. Gesetzlicher Ausschluss von objektiv begründeter Besorgnis getrennt; §§ 41–44, 45 Abs. 2 Satz 2, 47–49 ZPO amtlich gelesen. Verlust des Ablehnungsrechts, Glaubhaftmachung ohne eigene eidesstattliche Versicherung, dienstliche Äußerung und spätere Kenntnis erläutert. Nicht verwiesener § 45 Abs. 2 Satz 1 wird nicht ins Amtsverfahren übernommen.'),
'p58':('retained','Beide Absätze geprüft: Gerichts-/Staatsanwaltschaftsersuchen, angemeldete oder eingetragene Marke und divergierende Gutachten mehrerer Sachverständiger kumulativ. Ministerielle Genehmigung für außerhalb des gesetzlichen Aufgabenbereichs liegende Beschlüsse/Gutachten getrennt; kein privater Anspruch auf verbindliche Verletzungsfreistellung erfunden.'),
'p59':('retained','Beide Absätze geprüft. Amtsermittlung und fehlende Bindung an Vortrag/Beweisanträge nicht mit Befreiung von gesetzlichem Benutzungsnachweis gleichgesetzt. Vorherige Mitteilung neuer entscheidungstragender Umstände und bestimmte Äußerungsfrist sowie konkretes Recherchebeispiel stimmen mit dem Text überein.'),
'p60':('corrected','Drei Absätze vollständig geprüft. Aufklärungsmittel einschließlich eidlicher Vernehmung und Befugnisgrenzen konkretisiert. Aktuelle §-128a-Verweisung sowie §§ 160a, 162, 163 ZPO amtlich nachgelesen; Videoanhörung, Niederschrift, Genehmigung und Unterzeichnung abgegrenzt. Gewöhnlicher Sachdienlichkeitsanspruch und unbedingter Antragstatbestand im Verfalls-/Nichtigkeitsverfahren getrennt. Beispiel jetzt auf rechtserhebliche Warenbeschränkung ausgerichtet.'),
'p61':('corrected','Beide Absätze mit allen Sätzen geprüft. Verkündung ersetzt Zustellung nicht; unbeglaubigte Abschrift, Papierausfertigung und begrenzte Begründungsausnahme getrennt. Vier Belehrungsgegenstände, regulärer Fristbeginn, Jahresgrenze und schriftliche Negativbelehrung ausdrücklich erläutert. Entsprechende Anwendung auf Erinnerung und § 91 von bloßem Belehrungsmangel unterschieden.'),
'p62':('retained','Alle fünf Absätze und drei Ausschlussgründe gelesen. Vor Eintragung Antrag/berechtigtes Interesse/Glaubhaftmachung, danach Akteneinsicht, mögliche elektronische Gewährung und freie Registereinsicht sauber getrennt. Absatz 4 Nr. 2 bereits mit der seit 16.01.2026 berichtigten DSGVO-Bezeichnung; kein pauschaler öffentlicher Zugriff auf private Aktenbestandteile behauptet.'),
'p62a':('corrected','Einleitung, drei Nummern und Schlusssatz geprüft. Reichweite auf Daten im Register oder öffentlichen elektronischen Informationsdiensten beschränkt. Auskunft über Empfänger oder Empfängerkategorien nach Art. 15 Abs. 1 Buchst. c von einem vollständigen Auskunftsausschluss getrennt; Art. 19 Satz 2, Art. 21 Abs. 1 und Erfüllung des Kopierechts durch Einsicht einzeln erklärt. Keine pauschale Aufhebung von Datenschutz oder freien Weiterverwendung behauptet.'),
'p63':('corrected','Vier Absätze geprüft. Billigkeitskosten und notwendige Aufwendungen, fortbestehende Entscheidung nach Erledigung, Gegenstandswert und konkrete Kostenfestsetzung getrennt. RVG § 23 Abs. 3 Satz 2 und § 33 Abs. 1 amtlich gelesen; keine pauschale Übernahme der übrigen §-33-Rechtsmittelregeln. Bestimmte Gebührenrückzahlungen, Zweiwochenbeschwerde und zuständige Stelle für vollstreckbare Ausfertigung präzisiert.'),
'p64':('corrected','Alle sieben Absätze geprüft. Entscheiderstatus, aufschiebende Wirkung, Monatsfrist, Abhilfeausschluss und Gebührenrückzahlung beachtet. Direkte Wahl der Beschwerde nach Abs. 6 Satz 1 ausdrücklich ergänzt. Wechsel nach gegnerischer Beschwerde mit Zustellungsbeginn und Rücknahmefiktion von Beginn an gewähltem Weg unterschieden. Gegenstandslosigkeit späterer Erinnerungsentscheidung, § 158 Abs. 9 und amtlich nachgelesener § 6 Abs. 4 PatKostG erläutert.'),
'p64a':('retained','Kurze Kostenverweisung vollständig gelesen. Patentkostengesetz als Grundlage, keine erfundenen Gebührensätze und saubere Trennung von Verteilung nach § 63. Beispiel zur Fortsetzungsgebühr passt zu § 53 Abs. 5; rechtzeitige eigene Zahlung wird nicht durch einen späteren Erstattungsanspruch ersetzt.'),
'p65':('corrected','Zwei Absätze und sämtliche 15 Nummern gelesen und konkreter entfaltet. Gesetzesvorrang, getrennte Register, Lizenzangaben, elektronische Eingaben/amtliche Mitteilungen, Sprachen, personelle Aufgabenübertragung und deren Ausnahmen sowie Feiertage erläutert. Weiterübertragung nur durch Rechtsverordnung; keine unmittelbare Zulassung beliebiger Dateiformate aus der Ermächtigung abgeleitet.'),
'p65a':('retained','Vollständigen Satz gelesen: Tätigkeitsbereiche, nationale Ämter/WIPO/EUIPO und Angleichung der Instrumente zu Prüfung, Eintragung, Verwaltung und Löschung erfasst. Kein Anerkennungsautomatismus fremder Eintragungsentscheidungen behauptet. Fiktives Beispiel und praktische Schlusscheckliste bleiben zutreffend.'),
'p66':('corrected','Alle fünf Absätze einschließlich acht Sätzen des Abs. 3 gelesen. Einlegungsstelle/Monatsfrist, Beteiligtenstellung und aufschiebende Wirkung präzisiert. Gestufte sechs/zehn Monate, Entscheidungsantrag und zwei Monate, Einwilligung, weiterer Beschwerdewechsel und Rücknahmefiktion erläutert. Hemmung erfasst die Wartefristen der Sätze 1/2 einschließlich Zweimonatsfrist; nur Restlauf, kein Neubeginn. Erlass der Erinnerungsentscheidung, Austausch, Abhilfe/Vorlage und VKH-Vorabentscheidung getrennt; § 158 Abs. 9 genannt.'),
'p67':('retained','Drei Absätze und beide Modifikationen der GVG-Verweisung gelesen. Drei rechtskundige Mitglieder, Öffentlichkeit nach Eintragungsveröffentlichung, schutzwürdige Interessen auf Antrag und Verkündung vor Veröffentlichung erfasst. §§ 172–175 GVG amtlich nachgelesen; kein Anspruch auf beliebige geheime Prozessführung behauptet. Verhandlungsbedarf nach § 69 von Öffentlichkeit getrennt.'),
'p68':('retained','Beide Absätze gelesen. Öffentliche Interessen wahrende Erklärung/Terminteilnahme von gerichtlicher Anregung zum Beitritt und erst mit Eingang entstehender Beteiligtenstellung unterschieden. Mitteilungspflicht, Klangmarkenbeispiel und Kostengrenze des § 71 Abs. 2 zutreffend; keine geheime Entscheidungsgrundlage zugelassen.'),
'p69':('retained','Drei alternative Verhandlungsgründe gelesen: Beteiligtenantrag, gerichtliche Beweisaufnahme, Sachdienlichkeit. Antrag nicht zusätzlich von Sachdienlichkeit abhängig; Sonderfall unzulässiger Beschwerde nach § 70 Abs. 2 und vorbereitende Beweisaufnahme nach § 74 Abs. 2 geprüft. Kein pauschaler Anspruch auf jede gewünschte Beweisaufnahme behauptet.'),
'p70':('retained','Alle vier Absätze sowie drei Aufhebungsalternativen gelesen. Beschlussform, Entscheidung über Unzulässigkeit ohne Verhandlung, fehlende Amtsentscheidung/wesentlicher Mangel/wesentliche neue Tatsachen oder Beweise und gebundene rechtliche Beurteilung unterschieden. Zurückverweisung als Möglichkeit, nicht Automatismus erklärt. Beispiel zum übergangenen Gehör sachgerecht.'),
'p71':('corrected','Alle fünf Absätze geprüft. Eigene Kosten/Billigkeitsauferlegung, Anträge nach Beitritt der Amtsleitung, gesonderte Gebührenrückzahlung, Fortbestand nach Erledigung und Festsetzung/Vollstreckung erklärt. Zwei BPatG-Beschlüsse im gesamten amtlichen Volltext und örtlichen Korpus gelesen; präzise Rn. und enge Reichweite aufgenommen. Frühe Rücknahme allein trägt weder automatisch Kostenauferlegung noch Rückzahlung; keine absolute Ausnahmefreiheit behauptet.')}
baseline=json.loads((D/'commentary-baseline.json').read_text());before=baseline['commentary'];now=datetime.now(timezone.utc).isoformat();current={}
for p in sorted((W/'commentary').glob('*.md')):current.update(blocks(p.read_text()))
assert set(current)==set(before) and set(IDS)==set(notes)
changed=[i for i in current if current[i]!=before[i]];assert len(changed)==10 and set(changed)<=set(IDS)
for i in IDS:assert (i in changed)==(notes[i][0]=='corrected')
u={x['id']:x for x in map(json.loads,(W/'units.jsonl').read_text().splitlines())};r=E.parse(D/'markeng.xml').getroot();ns={n.attrib['doknr']:n for n in r.findall('norm')};compact=lambda x:re.sub(r'\s+','',x)
findings=[]
for i in IDS:
 x=u[i];n=ns[x['xml_doknr']];assert compact(x['text'])==compact(''.join(n.find('textdaten/text/Content').itertext()))
 findings.append(dict(id=i,label=x['label'],outcome=notes[i][0],finding=notes[i][1],resolved=True,source_xml_doknr=x['xml_doknr'],statutory_text_sha256=sht(x['text']),commentary_before_sha256=sht(before[i]),commentary_after_sha256=sht(current[i])))
cases=[]
for name,date,docket,scope,limit in [('kostenruecknahme','2011-01-11','24 W (pat) 46/09','Tenor und Gründe Rn. 1–4 (Rn. 4 Mitwirkendennamen)','Current § 71(1) and withdrawal alternative of (4) remain; decision only covers its own circumstances, not all subsequently added grounds. Actual reasoning rather than misleading XML norm metadata used.'),('gebuehrenruecknahme','2010-11-23','24 W (pat) 111/10','Tenor und Gründe Rn. 1–6','Current § 71(3) retains repayment power; only narrow point that early withdrawal alone did not justify repayment used; no historical fee amounts or complete old fee regime imported.')]:
 c=E.parse(D/(name+'.xml')).getroot();local=compact((D/(name+'-local.md')).read_text());count=0
 assert c.findtext('aktenzeichen')==docket and not c.findtext('ecli')
 for tag in ['tenor','gruende']:
  for p in c.findall('.//'+tag+'//p'):
   t=''.join(p.itertext()).strip()
   if t:assert compact(t) in local;count+=1
 cases.append(dict(court='BPatG',date=date,docket=docket,ecli=None,ecli_note='Official XML field empty; no ECLI invented',read_full_text=True,read_scope=scope,supported_reviewed_ids=['p71'],official_xml='sources/review-p55-p71/'+name+'.xml',official_xml_sha256=sha(D/(name+'.xml')),corpus_path='sources/review-p55-p71/'+name+'-local.md',corpus_sha256=sha(D/(name+'-local.md')),nonempty_official_paragraphs_compared=count,missing_from_read_corpus=0,card='cases/bpatg-'+name+'.md',superseded_law_check=limit))
q=json.loads((W/'quality-report.json').read_text());coverage=json.loads((W/'completeness-independent.json').read_text());assert coverage['ok']
assert not q['broken_local_links'] and not q['exact_repeated_paragraphs'] and not q['repeated_long_sentences'] and not q['placeholder_matches']
prior=json.loads((D/'prior-review-result.json').read_text());assert prior['complete'] and set(prior['reviewed_ids']).isdisjoint(IDS)
oldstatus=json.loads((W/'status.json').read_text());cumulative=list(dict.fromkeys(oldstatus['cumulative_reviewed_ids']+IDS));assert len(cumulative)==80
limitations=['Complete refers only to the exact 20 assigned units p55–p71 including p62a, p64a, p65a. Previous 60 reviewed units preserved without renewed substantive review; 111 units still await second pass.', 'Selective case research: two BPatG decisions read in full in local corpus and fresh official XML; no sufficiently specific additional case selected for the other 19 assigned units. No claim that no such case exists. Five previous BGH case cards not re-reviewed.', 'Current MarkenG consolidation and both 2026 amending/commencement texts checked. Current assigned changes in §§ 55 and 62 identified. Selective later-law search is not an exhaustive BGBl pipeline audit.', 'Historical § 158(6) and (9) identified; no full reconstruction of every old version. Limited external checks of ZPO, GVG, RVG and PatKostG individual provisions are not complete reviews of those codes. No independent full review of GDPR or implementing regulations.', 'Technical completeness, literal agreement, links and repetition checks do not establish legal errorlessness or external professional approval.']
validated='--validated' in sys.argv;technical=json.loads((W/'validation.json').read_text()) if validated else None
if validated:assert technical['ok'] and technical['verbatim_ratio']==1.0
result=dict(complete=validated,task='bounded_independent_second_pass',units_reviewed=20,reviewed_ids=IDS,decisive_date='2026-10-19',reviewed_at=now,unresolved_blockers=[],findings=findings,limitations=limitations,changed_ids=changed,retained_ids=[i for i in IDS if i not in changed],whole_book_complete=False,work_baseline_commit=baseline['work_baseline_commit'],baseline_evidence='sources/review-p55-p71/commentary-baseline.json',baseline_evidence_sha256=sha(D/'commentary-baseline.json'),unchanged_unassigned_units=171,unassigned_commentary_unchanged=True,prior_review_result='sources/review-p55-p71/prior-review-result.json',cumulative_reviewed_units=80,cumulative_reviewed_ids=cumulative,remaining_second_pass_units=111,case_checks=cases,source_preflight='preflight-result.json',source_verification='sources/verification.json',technical_validation=technical,technical_validation_pending=not validated,completeness=dict(expected=coverage['expected_count'],parsed=coverage['parsed_count'],missing=coverage['missing'],extra=coverage['unexpected'],xml_character_mismatch=coverage['xml_character_mismatch']),quality=dict(broken_links=q['broken_local_links'],repeated_long_sentences=q['repeated_long_sentences'],placeholder_matches=q['placeholder_matches']))
save(W/'review-result.json',result)
status=oldstatus;status.update(stage='bounded_second_pass_complete' if validated else 'bounded_second_pass_validation_pending',task_scope='Exactly p55–p71 including p62a, p64a, p65a; no whole-book completion.',reviewed_ids=IDS,units_reviewed=20,review_result='review-result.json',review_completed_at=now if validated else None,whole_book_review_complete=False,independent_second_pass='Current assigned 20 reviewed; 80 cumulatively reviewed, 111 pending',updated_at=now,remaining_limitations=limitations,unresolved_blockers=[],cumulative_reviewed_ids=cumulative,cumulative_reviewed_units=80,remaining_second_pass_units=111,commentary_characters=sum(map(len,current.values())))
status['source_checks']['latest_verification']=json.loads((W/'sources/verification.json').read_text())['last_verified_at']
status['case_law_sources']=[x for x in status['case_law_sources'] if x['docket'] not in [c['docket'] for c in cases]]+[{k:c[k] for k in ['court','date','docket','card','read_full_text']} for c in cases]
status['case_law_provenance']='Two BPatG cases fully read and fresh official XML verified in this batch; five previous BGH case cards retained without renewed substantive review.'
status['quality_checks'].update(output_local_links=q['checked_output_links'],broken_links=q['broken_local_links'],repeated_paragraphs=q['exact_repeated_paragraphs'],repeated_long_sentences=q['repeated_long_sentences'],other_commentary_blocks='All 171 unassigned commentary blocks unchanged against baseline '+baseline['work_baseline_commit'],unchanged_commentary_units=181,retained_reviewed_units=10,corrected_reviewed_units=10)
if validated:status['validation_result']=technical
save(W/'status.json',status)
search=dict(checked_at=now,queries=[dict(query='site:rechtsprechung-im-internet.de "24 W (pat) 46/09"',result='Firecrawl CLI: No results found; exit 0, no result file generated. Decisions located using local national corpus and verified directly at official download URL.'),dict(query='Markengesetz Änderung 2026 Oktober BGBl',evidence='sources/review-p55-p71-amendments-search.json',result='Official current MarkenG among results; third-party descriptions not used as substantive proof. No evidenced later amendment; absence not exhaustive proof.')],local_corpus_query='rg § 71.*MarkenG|MarkenG.*§ 71 in /Volumes/LaCie/law-intake/eu/de/rii; read MPRE177840964, MPRE176770964 and MPRE177010964; selected first two for direct relevance to separate cost issues',not_selected=[dict(doknr='MPRE177010964',reason='Read in local corpus only; no fresh official verification, not cited or used as authority')],fresh_fetches='sources/review-p55-p71/fetches.json',case_checks=cases,no_new_case_selected_ids=[i for i in IDS if i!='p71'],limit=limitations[1])
log=json.loads((W/'sources/search-log.json').read_text());log['bounded_review_p55_p71']=search;save(W/'sources/search-log.json',log);save(D/'search-log.json',search)
manifest=dict(created_at=now,primary_statute='markeng.xml',canonical_statute='canonical.md',files=[dict(path=str(p.relative_to(W)),bytes=p.stat().st_size,sha256=sha(p)) for p in sorted((W/'sources').rglob('*')) if p.is_file() and p.name!='manifest.json']);save(W/'sources/manifest.json',manifest)
